using System;
class ItemStack {public int count=1;public bool IsEmpty(){return count==0;}public ItemStack Clone(){return new ItemStack{count=count};}}
class XUiC_DragAndDropWindow {private ItemStack current=new ItemStack{count=0};public ItemStack CurrentStack {get{return current.Clone();}set{SetCurrentStack(value,false);}}public int Writes;public void SetCurrentStack(ItemStack value,bool sound){current=value.Clone();Writes++;}}
class Group {public bool isShowing;}
class Check {Group windowGroup;XUiC_DragAndDropWindow cursor;int returned;XUiC_DragAndDropWindow GetDragAndDropWindow(){return cursor;}void RestoreReservedCursorItem(ItemStack item){returned++;}
// METHODS
static void Main(){for(int mode=0;mode<5;mode++){var original=new ItemStack();var c=new Check{windowGroup=new Group{isShowing=true},cursor=new XUiC_DragAndDropWindow()};if(mode==1)c.windowGroup.isShowing=false;if(mode==2)c.cursor.CurrentStack=original;if(mode==3)c.cursor=null;if(mode==4)c.windowGroup=null;var item=new ItemStack();c.DeliverConfirmedPickup(item);if(mode==0){if(c.cursor.CurrentStack.count!=item.count||c.cursor.Writes!=1||ReferenceEquals(c.cursor.CurrentStack,item)||c.returned!=0)throw new Exception("Cursor delivery");}else{if(c.returned!=1)throw new Exception("Fallback");if(mode==2&&(c.cursor.CurrentStack.count!=original.count||c.cursor.Writes!=1))throw new Exception("Overwrote cursor");}}Console.WriteLine("PASS: actual confirmed pickup delivery uses empty open cursor, otherwise existing inventory-return path; occupied cursor preserved. Native inventory return substituted.");}}
